import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Gérer les connexions LIVE","description":"","frontmatter":{"title":"Gérer les connexions LIVE","docId":"user.live.connections","translationKey":"user.live.connections","locale":"fr","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"446118d4c202b645dd93867f1715484cbd9876f940ba229ac26e4b7f24bc4cbc","translationRevision":"20f0c5aed39f39927d1743b1760ee52eda296227c609ad9ed0ae63f81ab1a9bc","order":10},"headers":[],"relativePath":"fr/user/live/connections.md","filePath":"fr/user/live/connections.md","lastUpdated":1795735295000}`),s={name:`fr/user/live/connections.md`};function c(a,o,s,c,l,u){let d=e(`DemoFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="manage-live-connections" tabindex="-1">Gérer les connexions LIVE <a class="header-anchor" href="#manage-live-connections" aria-label="Permalink to “Gérer les connexions LIVE”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objectif et prérequis <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objectif et prérequis”">​</a></h2><p>Se connecter à un créateur précis, comprendre la reconnexion et configurer les serveurs de plugins indépendamment. Il vous faut une <a href="./../installation.html">installation de bureau</a> fonctionnelle, un accès réseau et l’identifiant du créateur. Consultez les <a href="./../requirements.html">prérequis</a> avant de diagnostiquer des problèmes de système d’exploitation.</p><h2 id="connect-deliberately" tabindex="-1">Se connecter de manière délibérée <a class="header-anchor" href="#connect-deliberately" aria-label="Permalink to “Se connecter de manière délibérée”">​</a></h2><ol><li>Ouvrez <strong>Connections</strong>. Saisissez l’identifiant, avec ou sans <code>@</code> ; un nom affiché n’est pas le même identifiant.</li><li>Laissez <strong>Use Cookie</strong> désactivé au départ. Si TikTok exige une session autorisée, activez cette option et saisissez le cookie uniquement dans le champ masqué. Les cookies restent en mémoire ; ne les collez pas dans les diagnostics ou les paramètres Cloud.</li><li>Laissez <strong>Monitor and auto-connect</strong> désactivé pour une tentative directe, puis sélectionnez <strong>Connect</strong>. Lisez l’état et toute erreur avant de réessayer.</li><li>Consultez <a href="./feed.html">Live feed</a> pour vérifier le créateur et la présence d’un nouvel événement. Une salle connectée mais calme peut ne montrer aucune activité.</li><li>Utilisez <strong>Reconnect</strong> pour le même créateur ou <strong>Disconnect</strong> avant d’en changer. Pendant une tentative en cours, <strong>Cancel</strong> l’arrête.</li></ol><p>Après une connexion directe réussie, activez la surveillance pour attendre qu’un créateur passe en direct. L’attente et la vérification sont distinctes de la connexion établie. Arrêtez la surveillance avant de modifier un identifiant verrouillé. Sélectionner un créateur récent démarre une connexion ; cela ne remplit pas simplement le champ.</p><p>L’explorateur propose des salles découvertes, mais les résultats peuvent devenir obsolètes. Actualisez-les avant de supposer qu’une salle est toujours disponible. Les connexions des serveurs de plugins dans le panneau inférieur configurent leurs propres services ; un plugin connecté n’authentifie ni TikTok ni Cloud.</p><h2 id="expected-result-and-status" tabindex="-1">Résultat attendu et état <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Résultat attendu et état”">​</a></h2><p>Les connexions directes, la surveillance et les commandes de connexion des plugins sont disponibles. La reconnexion au même créateur conserve le contexte du flux actuel ; changer de créateur ouvre un autre contexte. L’accès réel à TikTok dépend de la salle et de la session distantes ; un test local réussi ne le garantit pas.</p><h2 id="recovery" tabindex="-1">Récupération <a class="header-anchor" href="#recovery" aria-label="Permalink to “Récupération”">​</a></h2><p>Pour une salle hors ligne, vérifiez que le créateur diffuse en direct. En cas d’erreur de session ou de limitation de débit, respectez la condition de nouvelle tentative indiquée. Cliquer plusieurs fois sur la reconnexion ne renouvelle pas l’authentification. Consultez le <a href="./../preferences/troubleshooting.html">dépannage</a> pour recueillir le composant en échec et l’heure sans exposer d’identifiants.</p><p>Essayez interactivement avant de toucher à votre vraie configuration :</p>`,12),t(d,{scenario:`connection`,locale:`fr`,panel:`connection`,title:`Essayez le panneau de connexion LIVE`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Opérations en ligne de commande <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Opérations en ligne de commande”">​</a></h2><p>Chaque opération de ce guide est aussi disponible depuis la CLI — hors ligne, scriptable et adaptée aux agents. Les lignes d&#39;usage sont la syntaxe du parseur et restent en anglais dans toutes les langues.</p><table tabindex="0"><thead><tr><th>Commande</th><th>Résumé</th></tr></thead><tbody><tr><td><code>tiktools live connect --unique-id &lt;id&gt; --session-cookie &lt;cookie&gt; [--room-id &lt;id&gt;]</code></td><td>se connecter à une salle en direct</td></tr><tr><td><code>tiktools live pick --session-cookie &lt;cookie&gt;</code></td><td>choisir une salle en direct interactivement</td></tr><tr><td><code>tiktools live channels [--keyword text] [--offset N] [--limit N] [--session-cookie &lt;cookie&gt;]</code></td><td>découvrir les chaînes en direct ; fonctionne sans session</td></tr><tr><td><code>tiktools live disconnect</code></td><td>se déconnecter de la salle actuelle <strong>destructif</strong></td></tr><tr><td><code>tiktools live status</code></td><td>état actuel de la connexion</td></tr></tbody></table><p>Consultez la <a href="./../../developer/cli.html">référence complète des commandes</a> pour les conventions, la sortie JSON et les marqueurs d’opérations destructives.</p>`,4)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};